import { ArrowDown, Check, ChevronDown, ChevronUp, Copy, Search, WrapText } from 'lucide-react';
import {
  useEffect,
  useId,
  useImperativeHandle,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent,
  type ReactNode,
  type Ref,
} from 'react';
import { useI18n } from '../../i18n/I18nProvider';
import { cn } from '../../utils/cn';
import { ansiClassName, parseAnsiState, type AnsiSegment, type AnsiStyle } from './ansi';
import { appendChunk, EMPTY_BUFFER, toBufferLine, trimBuffer, type BufferLine, type TerminalBuffer, type TerminalLine } from './buffer';
import { terminalVariants } from './terminal.variants';

export type { TerminalLine } from './buffer';

/** Imperative API (`ref`): stream output into an uncontrolled Terminal. */
export interface TerminalHandle {
  /** Appends raw output; a chunk without a trailing newline leaves the line open for the next one. */
  write: (chunk: string) => void;
  /** Appends one complete line. */
  writeln: (line?: string) => void;
  /** Removes every line. */
  clear: () => void;
  /** Scrolls to the newest line and resumes following the tail. */
  scrollToBottom: () => void;
  /** All output as plain text (escapes stripped). */
  getText: () => string;
}

export interface TerminalProps {
  /** Controlled output (ANSI escapes allowed). Without it, stream through the `ref` handle. */
  lines?: readonly TerminalLine[];
  /** Initial output of an uncontrolled Terminal. */
  defaultLines?: readonly TerminalLine[];
  ref?: Ref<TerminalHandle>;
  /** Oldest lines beyond this are dropped (line numbers keep counting). Default 5000. */
  maxLines?: number;
  showLineNumbers?: boolean;
  /** Shows each line's time (lines written through the handle are stamped on arrival). */
  showTimestamps?: boolean;
  formatTimestamp?: (date: Date) => string;
  wrap?: boolean;
  defaultWrap?: boolean;
  onWrapChange?: (wrap: boolean) => void;
  /** Toolbar title, e.g. the command or job name. */
  title?: ReactNode;
  /** Accessible name of the log. Default: "Terminal output". */
  label?: string;
  /**
   * Announce new output to screen readers. Off by default (a busy log is noise); opt in with
   * `true` / `'polite'` for slow, meaningful output, `'assertive'` only for urgent streams.
   */
  live?: boolean | 'polite' | 'assertive';
  /** Show the toolbar (title, search, wrap, copy). Default true. */
  toolbar?: boolean;
  searchable?: boolean;
  copyable?: boolean;
  wrapToggle?: boolean;
  /** Shown while there is no output. */
  emptyText?: ReactNode;
  className?: string;
}

interface Match {
  line: number;
  start: number;
  end: number;
}

const BOTTOM_SLACK = 8;

/** Parses every line, carrying the ANSI style across lines like a real terminal. */
function parseLines(lines: readonly BufferLine[]) {
  let style: AnsiStyle = {};
  return lines.map((line) => {
    const result = parseAnsiState(line.text, style);
    style = result.style;
    return { segments: result.segments, plain: result.segments.map((seg) => seg.text).join('') };
  });
}

/** Segments of one line with the search matches cut out as `<mark>`s. */
function renderSegments(segments: AnsiSegment[], matches: Match[], currentKey: string | null, markClass: string, lineIndex: number) {
  if (!matches.length) {
    return segments.map((seg, i) => {
      const cls = ansiClassName(seg);
      return cls ? (
        <span key={i} className={cls}>
          {seg.text}
        </span>
      ) : (
        seg.text
      );
    });
  }
  const out: ReactNode[] = [];
  let offset = 0;
  segments.forEach((seg, i) => {
    const cls = ansiClassName(seg) || undefined;
    const segStart = offset;
    const segEnd = offset + seg.text.length;
    let cursor = segStart;
    for (const m of matches) {
      if (m.end <= cursor || m.start >= segEnd) continue;
      const from = Math.max(m.start, cursor);
      const to = Math.min(m.end, segEnd);
      if (from > cursor) out.push(<span key={`${i}-${cursor}`} className={cls}>{seg.text.slice(cursor - segStart, from - segStart)}</span>);
      const key = `${lineIndex}:${m.start}`;
      out.push(
        <mark key={`${i}-m${from}`} className={cn(markClass, cls)} data-current={key === currentKey || undefined} data-match={key}>
          {seg.text.slice(from - segStart, to - segStart)}
        </mark>,
      );
      cursor = to;
    }
    if (cursor < segEnd) out.push(<span key={`${i}-${cursor}`} className={cls}>{seg.text.slice(cursor - segStart)}</span>);
    offset = segEnd;
  });
  return out;
}

/**
 * Streamed command output: ANSI colours mapped to tokens, tail following with "Jump to latest",
 * optional line numbers / timestamps, wrap toggle, copy all, search highlight and a line cap.
 * The output is a `role="log"` (aria-live off unless `live`).
 */
export function Terminal({
  lines: linesProp,
  defaultLines,
  ref,
  maxLines = 5000,
  showLineNumbers = false,
  showTimestamps = false,
  formatTimestamp,
  wrap: wrapProp,
  defaultWrap = false,
  onWrapChange,
  title,
  label,
  live = false,
  toolbar = true,
  searchable = true,
  copyable = true,
  wrapToggle = true,
  emptyText,
  className,
}: TerminalProps) {
  const { t, locale } = useI18n();
  const [inner, setInner] = useState<TerminalBuffer>(() =>
    trimBuffer({ ...EMPTY_BUFFER, lines: (defaultLines ?? []).map(toBufferLine) }, maxLines),
  );
  const buffer = useMemo<TerminalBuffer>(
    () => (linesProp ? trimBuffer({ ...EMPTY_BUFFER, lines: linesProp.map(toBufferLine) }, maxLines) : trimBuffer(inner, maxLines)),
    [linesProp, inner, maxLines],
  );
  const [innerWrap, setInnerWrap] = useState(defaultWrap);
  const wrap = wrapProp ?? innerWrap;
  const [following, setFollowing] = useState(true);
  const [seenTotal, setSeenTotal] = useState(0);
  const [query, setQuery] = useState('');
  const [current, setCurrent] = useState(0);
  const [copyStatus, setCopyStatus] = useState<'idle' | 'copied' | 'failed'>('idle');
  const viewportRef = useRef<HTMLDivElement>(null);
  const searchRef = useRef<HTMLInputElement>(null);
  const searchId = useId();
  const s = terminalVariants({ wrap });

  const total = buffer.first + buffer.lines.length;

  const parsed = useMemo(() => parseLines(buffer.lines), [buffer.lines]);

  const matches = useMemo<Match[]>(() => {
    const q = query.trim().toLocaleLowerCase(locale);
    if (!q) return [];
    const found: Match[] = [];
    parsed.forEach((line, index) => {
      const hay = line.plain.toLocaleLowerCase(locale);
      let at = hay.indexOf(q);
      while (at >= 0) {
        found.push({ line: index, start: at, end: at + q.length });
        at = hay.indexOf(q, at + q.length);
      }
    });
    return found;
  }, [parsed, query, locale]);
  const currentIndex = matches.length ? Math.min(current, matches.length - 1) : -1;
  const currentMatch = currentIndex >= 0 ? matches[currentIndex] : undefined;
  const currentKey = currentMatch ? `${currentMatch.line}:${currentMatch.start}` : null;

  const scrollToBottom = () => {
    const el = viewportRef.current;
    if (el) el.scrollTop = el.scrollHeight;
    setFollowing(true);
  };

  useImperativeHandle(
    ref,
    () => ({
      write: (chunk) => setInner((prev) => appendChunk(prev, chunk, maxLines)),
      writeln: (line = '') => setInner((prev) => appendChunk(prev, `${prev.open ? '\n' : ''}${line}\n`, maxLines)),
      clear: () => setInner(EMPTY_BUFFER),
      scrollToBottom,
      getText: () => parsed.map((line) => line.plain).join('\n'),
    }),
    [maxLines, parsed],
  );

  // Follow the tail while the user has not scrolled up.
  useLayoutEffect(() => {
    if (!following || currentKey) return;
    const el = viewportRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [total, buffer.lines, following, currentKey]);

  // Bring the current search match into view.
  useEffect(() => {
    if (!currentKey) return;
    const mark = viewportRef.current?.querySelector(`[data-match="${currentKey}"]`);
    if (mark && 'scrollIntoView' in mark && typeof mark.scrollIntoView === 'function') mark.scrollIntoView({ block: 'nearest', inline: 'nearest' });
  }, [currentKey]);

  useEffect(() => {
    if (copyStatus === 'idle') return;
    const id = window.setTimeout(() => setCopyStatus('idle'), 2000);
    return () => window.clearTimeout(id);
  }, [copyStatus]);

  const onScroll = () => {
    const el = viewportRef.current;
    if (!el) return;
    const atBottom = el.scrollHeight - el.scrollTop - el.clientHeight <= BOTTOM_SLACK;
    if (atBottom !== following) {
      setFollowing(atBottom);
      if (!atBottom) setSeenTotal(total);
    }
  };

  const onViewportKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    const el = viewportRef.current;
    if (!el) return;
    if (e.key === 'End' && !e.shiftKey) {
      e.preventDefault();
      scrollToBottom();
    } else if (e.key === 'Home' && !e.shiftKey) {
      e.preventDefault();
      el.scrollTop = 0;
      setFollowing(false);
      setSeenTotal(total);
    }
  };

  const onRootKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (searchable && toolbar && (e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'f') {
      e.preventDefault();
      searchRef.current?.focus();
      searchRef.current?.select();
    }
  };

  const step = (delta: number) => {
    if (!matches.length) return;
    if (following) setSeenTotal(total);
    setFollowing(false);
    setCurrent((c) => (Math.min(c, matches.length - 1) + delta + matches.length) % matches.length);
  };

  const onSearchKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      step(e.shiftKey ? -1 : 1);
    } else if (e.key === 'Escape' && query) {
      e.preventDefault();
      e.stopPropagation();
      setQuery('');
      setCurrent(0);
    }
  };

  const copyAll = async () => {
    try {
      await navigator.clipboard.writeText(parsed.map((line) => line.plain).join('\n'));
      setCopyStatus('copied');
    } catch {
      setCopyStatus('failed');
    }
  };

  const toggleWrap = () => {
    const next = !wrap;
    setInnerWrap(next);
    onWrapChange?.(next);
  };

  const unseen = following ? 0 : Math.max(0, total - seenTotal);
  const digits = String(Math.max(total, 1)).length;
  const timeFormat = useMemo(() => {
    if (formatTimestamp) return formatTimestamp;
    const fmt = new Intl.DateTimeFormat(locale, { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false });
    return (d: Date) => fmt.format(d);
  }, [formatTimestamp, locale]);
  const ariaLive = live === true ? 'polite' : live || 'off';
  const announcement = copyStatus === 'copied' ? t('common.copiedToClipboard') : copyStatus === 'failed' ? t('common.copyFailed') : '';

  return (
    <div className={cn(s.root(), className)} onKeyDown={onRootKeyDown}>
      {toolbar && (
        <div className={s.header()}>
          {title && <span className={s.title()}>{title}</span>}
          <div className={s.actions()}>
            {searchable && (
              <div className={s.search()}>
                <Search size={12} aria-hidden className="shrink-0" />
                <input
                  ref={searchRef}
                  id={searchId}
                  type="search"
                  value={query}
                  onChange={(e) => {
                    setQuery(e.target.value);
                    setCurrent(0);
                  }}
                  onKeyDown={onSearchKeyDown}
                  aria-label={t('terminal.search')}
                  placeholder={t('common.searchPlaceholder')}
                  className={s.searchInput()}
                />
                {query.trim() && (
                  <span className={s.matches()} aria-live="polite">
                    {matches.length ? t('terminal.matches', { current: currentIndex + 1, total: matches.length }) : t('terminal.noMatches')}
                  </span>
                )}
                <button type="button" className={s.button()} aria-label={t('terminal.previousMatch')} disabled={!matches.length} onClick={() => step(-1)}>
                  <ChevronUp size={13} aria-hidden />
                </button>
                <button type="button" className={s.button()} aria-label={t('terminal.nextMatch')} disabled={!matches.length} onClick={() => step(1)}>
                  <ChevronDown size={13} aria-hidden />
                </button>
              </div>
            )}
            {wrapToggle && (
              <button type="button" className={s.button()} aria-label={t('terminal.wrap')} aria-pressed={wrap} onClick={toggleWrap}>
                <WrapText size={14} aria-hidden />
              </button>
            )}
            {copyable && (
              <button
                type="button"
                className={cn(s.button(), copyStatus === 'copied' && s.copied())}
                aria-label={t('terminal.copyAll')}
                disabled={!buffer.lines.length}
                onClick={copyAll}
              >
                {copyStatus === 'copied' ? <Check size={14} aria-hidden /> : <Copy size={14} aria-hidden />}
              </button>
            )}
          </div>
        </div>
      )}
      <div className={s.body()}>
        <div
          ref={viewportRef}
          role="log"
          aria-live={ariaLive}
          aria-label={label ?? t('terminal.label')}
          tabIndex={0}
          onScroll={onScroll}
          onKeyDown={onViewportKeyDown}
          className={s.viewport()}
        >
          {buffer.lines.length === 0 && emptyText ? <div className={s.empty()}>{emptyText}</div> : null}
          <div className={s.lines()}>
            {buffer.lines.map((line, index) => {
              const number = buffer.first + index + 1;
              const lineMatches = matches.length ? matches.filter((m) => m.line === index) : [];
              const segments = parsed[index]?.segments ?? [];
              return (
                <div key={number} className={s.line()} data-current={currentMatch?.line === index || undefined}>
                  {showLineNumbers && (
                    <span aria-hidden className={s.lineNumber()} style={{ minWidth: `${digits}ch` }}>
                      {number}
                    </span>
                  )}
                  {showTimestamps && line.timestamp !== undefined && (
                    <time dateTime={new Date(line.timestamp).toISOString()} className={s.timestamp()}>
                      {timeFormat(new Date(line.timestamp))}
                    </time>
                  )}
                  <span className={s.content()}>{segments.length ? renderSegments(segments, lineMatches, currentKey, s.mark(), index) : '​'}</span>
                </div>
              );
            })}
          </div>
        </div>
        {!following && (
          <button type="button" className={s.jump()} onClick={scrollToBottom}>
            <ArrowDown size={13} aria-hidden />
            {t('terminal.jumpToLatest')}
            {unseen > 0 && <span className="text-muted-foreground">· {t('terminal.newLines', { count: unseen })}</span>}
          </button>
        )}
      </div>
      <span role="status" className="sr-only">
        {announcement}
      </span>
    </div>
  );
}

/**
 * ANSI escape handling for Terminal: SGR (`ESC[…m`) styles become segments; every other escape
 * sequence (cursor moves, OSC titles / links, …) is dropped. Colours map to TOKEN classes only.
 */

export const ANSI_COLORS = ['black', 'red', 'green', 'yellow', 'blue', 'magenta', 'cyan', 'white'] as const;
export type AnsiBaseColor = (typeof ANSI_COLORS)[number];
/** The 8 normal colours and their 8 bright variants (`brightRed`…). 256 / true colours snap to these. */
export type AnsiColor = AnsiBaseColor | `bright${Capitalize<AnsiBaseColor>}`;

export interface AnsiStyle {
  fg?: AnsiColor;
  bg?: AnsiColor;
  bold?: boolean;
  dim?: boolean;
  italic?: boolean;
  underline?: boolean;
  inverse?: boolean;
  strikethrough?: boolean;
}

export interface AnsiSegment extends AnsiStyle {
  text: string;
}

const ESC = 27;
const BEL = 7;

const bright = (c: AnsiBaseColor): AnsiColor => `bright${c[0]?.toUpperCase()}${c.slice(1)}` as AnsiColor;
const color = (index: number, isBright: boolean): AnsiColor | undefined => {
  const base = ANSI_COLORS[index];
  if (!base) return undefined;
  return isBright ? bright(base) : base;
};

/** RGB (0–255) → nearest of the 16 colours: each channel on/off, bright when any channel is high. */
function snapRgb(r: number, g: number, b: number): AnsiColor | undefined {
  const index = (r >= 128 ? 1 : 0) | (g >= 128 ? 2 : 0) | (b >= 128 ? 4 : 0);
  const max = Math.max(r, g, b);
  if (index === 0) return max >= 64 ? 'brightBlack' : 'black';
  return color(index, max >= 200 && index !== 7 ? true : index === 7 && max >= 230);
}

/** xterm 256-colour index → one of the 16. */
function snap256(n: number): AnsiColor | undefined {
  if (n < 8) return color(n, false);
  if (n < 16) return color(n - 8, true);
  if (n >= 232) {
    const level = 8 + (n - 232) * 10;
    return level < 64 ? 'black' : level < 160 ? 'brightBlack' : level < 230 ? 'white' : 'brightWhite';
  }
  const cube = n - 16;
  const steps = [0, 95, 135, 175, 215, 255];
  return snapRgb(steps[Math.floor(cube / 36) % 6] ?? 0, steps[Math.floor(cube / 6) % 6] ?? 0, steps[cube % 6] ?? 0);
}

/** Applies one SGR parameter list to a style (mutates `style`). */
function applySgr(style: AnsiStyle, params: number[]) {
  if (params.length === 0) params = [0];
  for (let i = 0; i < params.length; i++) {
    const p = params[i] ?? 0;
    if (p === 0) {
      for (const key of Object.keys(style) as Array<keyof AnsiStyle>) delete style[key];
    } else if (p === 1) style.bold = true;
    else if (p === 2) style.dim = true;
    else if (p === 3) style.italic = true;
    else if (p === 4) style.underline = true;
    else if (p === 7) style.inverse = true;
    else if (p === 9) style.strikethrough = true;
    else if (p === 21 || p === 22) {
      delete style.bold;
      delete style.dim;
    } else if (p === 23) delete style.italic;
    else if (p === 24) delete style.underline;
    else if (p === 27) delete style.inverse;
    else if (p === 29) delete style.strikethrough;
    else if (p >= 30 && p <= 37) style.fg = color(p - 30, false);
    else if (p >= 90 && p <= 97) style.fg = color(p - 90, true);
    else if (p === 39) delete style.fg;
    else if (p >= 40 && p <= 47) style.bg = color(p - 40, false);
    else if (p >= 100 && p <= 107) style.bg = color(p - 100, true);
    else if (p === 49) delete style.bg;
    else if (p === 38 || p === 48) {
      const mode = params[i + 1];
      let value: AnsiColor | undefined;
      if (mode === 5) {
        value = snap256(params[i + 2] ?? 0);
        i += 2;
      } else if (mode === 2) {
        value = snapRgb(params[i + 2] ?? 0, params[i + 3] ?? 0, params[i + 4] ?? 0);
        i += 4;
      } else {
        i += 1;
      }
      if (p === 38) style.fg = value;
      else style.bg = value;
    }
  }
}

const sameStyle = (a: AnsiStyle, b: AnsiStyle) =>
  a.fg === b.fg &&
  a.bg === b.bg &&
  !!a.bold === !!b.bold &&
  !!a.dim === !!b.dim &&
  !!a.italic === !!b.italic &&
  !!a.underline === !!b.underline &&
  !!a.inverse === !!b.inverse &&
  !!a.strikethrough === !!b.strikethrough;

const snapshot = (style: AnsiStyle): AnsiStyle => {
  const out: AnsiStyle = {};
  for (const [key, value] of Object.entries(style) as Array<[keyof AnsiStyle, AnsiStyle[keyof AnsiStyle]]>) {
    if (value !== undefined && value !== false) (out as Record<string, unknown>)[key] = value;
  }
  return out;
};

/**
 * Parses text with ANSI escapes into styled segments, starting from `initial` (the style carried
 * over from earlier output). Returns the segments and the style in effect at the end.
 */
export function parseAnsiState(text: string, initial: AnsiStyle = {}): { segments: AnsiSegment[]; style: AnsiStyle } {
  const segments: AnsiSegment[] = [];
  const style: AnsiStyle = { ...initial };
  let current = snapshot(style);
  let buffer = '';
  const flush = () => {
    if (!buffer) return;
    const last = segments[segments.length - 1];
    if (last && sameStyle(last, current)) last.text += buffer;
    else segments.push({ ...current, text: buffer });
    buffer = '';
  };
  let i = 0;
  while (i < text.length) {
    const code = text.charCodeAt(i);
    if (code === ESC) {
      const kind = text[i + 1];
      if (kind === '[') {
        let j = i + 2;
        while (j < text.length && !(text.charCodeAt(j) >= 0x40 && text.charCodeAt(j) <= 0x7e)) j++;
        if (text[j] === 'm') {
          const raw = text.slice(i + 2, j);
          const params = raw === '' ? [] : raw.split(/[;:]/).map((n) => (n === '' ? 0 : Number.parseInt(n, 10) || 0));
          flush();
          applySgr(style, params);
          current = snapshot(style);
        }
        i = j + 1;
      } else if (kind === ']') {
        let j = i + 2;
        while (j < text.length && text.charCodeAt(j) !== BEL && !(text.charCodeAt(j) === ESC && text[j + 1] === '\\')) j++;
        i = text.charCodeAt(j) === BEL ? j + 1 : j + 2;
      } else {
        i += 2;
      }
      continue;
    }
    // Drop other C0 controls except tab and newline.
    if (code < 32 && code !== 9 && code !== 10) {
      i++;
      continue;
    }
    buffer += text[i];
    i++;
  }
  flush();
  return { segments, style: snapshot(style) };
}

/** Parses text with ANSI SGR escapes into styled segments (other escapes are dropped). */
export function parseAnsi(text: string, initial?: AnsiStyle): AnsiSegment[] {
  return parseAnsiState(text, initial).segments;
}

/** The text without any escape sequence. */
export function stripAnsi(text: string): string {
  return parseAnsi(text)
    .map((s) => s.text)
    .join('');
}

/**
 * ANSI colour → token text class. Only contrast-safe tokens: blue and cyan both use `text-info`
 * (the category cyan is below AA on the light theme); bright variants reuse their base token.
 */
export const ANSI_TEXT_CLASS: Record<AnsiBaseColor, string> = {
  black: 'text-muted-foreground',
  red: 'text-destructive-text',
  green: 'text-success-text',
  yellow: 'text-warning-text',
  blue: 'text-info',
  magenta: 'text-category-violet',
  cyan: 'text-info',
  white: 'text-foreground',
};

/** ANSI background → token tint (text keeps its own token, so it stays readable). */
export const ANSI_BG_CLASS: Record<AnsiBaseColor, string> = {
  black: 'bg-muted',
  red: 'bg-destructive/15',
  green: 'bg-success/15',
  yellow: 'bg-warning/15',
  blue: 'bg-info/15',
  magenta: 'bg-category-violet/15',
  cyan: 'bg-category-cyan/15',
  white: 'bg-foreground/10',
};

const baseOf = (c: AnsiColor): AnsiBaseColor =>
  (c.startsWith('bright') ? c.slice(6).toLowerCase() : c) as AnsiBaseColor;

/** Token classes for a segment's style (empty string for plain text). Inverse uses foreground / background. */
export function ansiClassName(style: AnsiStyle): string {
  const classes: string[] = [];
  if (style.inverse) classes.push('bg-foreground text-background');
  else {
    if (style.fg) classes.push(ANSI_TEXT_CLASS[baseOf(style.fg)]);
    else if (style.dim) classes.push('text-muted-foreground');
    if (style.bg) classes.push(ANSI_BG_CLASS[baseOf(style.bg)]);
  }
  if (style.bold || style.fg?.startsWith('bright')) classes.push('font-semibold');
  if (style.italic) classes.push('italic');
  if (style.underline) classes.push('underline');
  if (style.strikethrough) classes.push('line-through');
  return classes.join(' ');
}

/** One line of terminal output: raw text (ANSI escapes allowed) and an optional timestamp. */
export type TerminalLine = string | { text: string; timestamp?: Date | number | string };

export interface BufferLine {
  text: string;
  timestamp?: number;
}

export interface TerminalBuffer {
  lines: BufferLine[];
  /** Absolute index of `lines[0]` (lines dropped by `maxLines` keep the numbering stable). */
  first: number;
  /** The last line has no trailing newline yet: the next chunk continues it. */
  open: boolean;
}

export const EMPTY_BUFFER: TerminalBuffer = { lines: [], first: 0, open: false };

/**
 * A carriage return rewrites the line (progress bars): keep what follows the last one. A trailing
 * `\r` on an open line is kept (the rewrite may arrive in the next chunk); on a complete line it is CRLF.
 */
function collapseCarriageReturns(text: string, complete: boolean): string {
  const t = complete && text.endsWith('\r') ? text.slice(0, -1) : text;
  const end = t.endsWith('\r') ? t.length - 1 : t.length;
  const at = end > 0 ? t.lastIndexOf('\r', end - 1) : -1;
  return at < 0 ? t : t.slice(at + 1);
}

export function toBufferLine(line: TerminalLine): BufferLine {
  if (typeof line === 'string') return { text: line };
  const ts = line.timestamp === undefined ? undefined : new Date(line.timestamp).getTime();
  return { text: line.text, timestamp: Number.isNaN(ts) ? undefined : ts };
}

/** Drops the oldest lines beyond `maxLines`. */
export function trimBuffer(buffer: TerminalBuffer, maxLines: number): TerminalBuffer {
  const extra = buffer.lines.length - Math.max(1, maxLines);
  if (extra <= 0) return buffer;
  return { ...buffer, lines: buffer.lines.slice(extra), first: buffer.first + extra };
}

/** Appends a streamed chunk: splits on newlines, continues an open last line, honours `\r`. */
export function appendChunk(buffer: TerminalBuffer, chunk: string, maxLines: number, now = Date.now()): TerminalBuffer {
  if (chunk === '') return buffer;
  const lines = buffer.lines.slice();
  const parts = chunk.split('\n');
  const tail = parts.pop() ?? '';
  let open = buffer.open;
  const add = (part: string, complete: boolean) => {
    const last = lines[lines.length - 1];
    if (open && last) lines[lines.length - 1] = { ...last, text: collapseCarriageReturns(last.text + part, complete) };
    else lines.push({ text: collapseCarriageReturns(part, complete), timestamp: now });
  };
  for (const part of parts) {
    add(part, true);
    open = false;
  }
  if (tail !== '') {
    add(tail, false);
    open = true;
  }
  return trimBuffer({ lines, first: buffer.first, open }, maxLines);
}

